"""Compile the standalone incremental-backup harness without rebuilding production."""

import argparse
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import zipfile


REPO = Path(__file__).resolve().parents[1]
MAIN = "org.eclipse.rdf4j.sail.lmdb.LmdbIncrementalBackupThroughputBenchmark"
SOURCE = REPO / "core/sail/lmdb/src/test/java" / (MAIN.replace(".", "/") + ".java")


def sha256(path):
    digest = hashlib.sha256()
    with Path(path).open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def classpath_entries(path):
    entries = [Path(part).resolve() for part in Path(path).read_text().strip().split(os.pathsep) if part]
    if not entries:
        raise ValueError("Classpath must not be empty")
    for entry in entries:
        if not entry.exists():
            raise FileNotFoundError(entry)
    return entries


def manifest_bytes(entries, source_sha):
    # JAR manifest continuation lines are limited to 72 bytes, including CRLF.
    urls = [entry.as_uri() + ("/" if entry.is_dir() else "") for entry in entries]
    attributes = [
        ("Manifest-Version", "1.0"),
        ("Main-Class", MAIN),
        ("Benchmark-Source-SHA256", source_sha),
        ("Class-Path", " ".join(urls)),
    ]
    result = bytearray()
    for key, value in attributes:
        remaining = (key + ": " + value).encode("utf-8")
        result.extend(remaining[:70] + b"\r\n")
        remaining = remaining[70:]
        while remaining:
            result.extend(b" " + remaining[:69] + b"\r\n")
            remaining = remaining[69:]
    result.extend(b"\r\n")
    return bytes(result)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--classpath-file", required=True, type=Path)
    parser.add_argument("--source", type=Path, default=SOURCE,
                        help="Explicit harness source; useful for an isolated prepared source before repository edits")
    parser.add_argument("--javac", default=shutil.which("javac"))
    parser.add_argument("--output", type=Path,
                        default=REPO / "core/sail/lmdb/target/backup-throughput-harness.jar")
    args = parser.parse_args()
    if not args.javac:
        parser.error("Specify a JDK 25+ javac using --javac or PATH")
    entries = classpath_entries(args.classpath_file)
    source = args.source.resolve()
    output = args.output.resolve()
    output.parent.mkdir(parents=True, exist_ok=True)
    source_sha = sha256(source)
    with tempfile.TemporaryDirectory(prefix="backup-harness-", dir=output.parent) as temporary:
        temporary = Path(temporary)
        classes = temporary / "classes"
        classes.mkdir()
        empty_sources = temporary / "empty-sourcepath"
        empty_sources.mkdir()
        command = [str(args.javac), "-J-Xmx256m", "-proc:none", "-implicit:none", "-encoding", "UTF-8", "-g",
                   "-sourcepath", str(empty_sources), "-classpath", os.pathsep.join(map(str, entries)),
                   "-d", str(classes), str(source)]
        subprocess.run(command, check=True)
        class_files = sorted(classes.rglob("*.class"))
        if not class_files or any(not path.name.startswith("LmdbIncrementalBackupThroughputBenchmark")
                                  for path in class_files):
            raise RuntimeError("Harness compilation produced unexpected classes")
        staged = temporary / "harness.jar"
        with zipfile.ZipFile(staged, "w", zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("META-INF/MANIFEST.MF", manifest_bytes(entries, source_sha))
            for path in class_files:
                archive.write(path, path.relative_to(classes).as_posix())
        with zipfile.ZipFile(staged) as archive:
            if archive.testzip() is not None:
                raise RuntimeError("Harness JAR integrity check failed")
        metadata = {
            "source": str(source), "source_sha256": source_sha, "command": command,
            "classpath": list(map(str, entries)),
            "classes": {path.relative_to(classes).as_posix(): sha256(path) for path in class_files},
            "jar_sha256": sha256(staged),
        }
        os.replace(staged, output)
        output.with_suffix(".json").write_text(json.dumps(metadata, indent=2) + "\n")
    print(json.dumps({"jar": str(output), "sha256": sha256(output), "class_count": len(class_files)}))


if __name__ == "__main__":
    main()
